    "pro-yuk-tasima-arabasi": { code: "KY-600", aboutParagraph: "Für den Transport schwerer Lasten konzipiert, wird dieser Servicewagen für Materialtransporte in Lagern, Lagerräumen und der Logistik hinter dem Verkaufsraum eingesetzt. Mit einer Tragfähigkeit von 600 kg misst das Modell 65x95x155 cm und wiegt etwa 40 kg. Der Einsatz von verzinkte Beschichtung in diesem Produkt sorgt für eine lange Lebensdauer bei hoher Beständigkeit gegen Korrosion und starke tägliche Beanspruchung. Spart spürbar Arbeitszeit bei Wareneingang, Inventur und internen Transfers ein.", galleryImages: ["/assets/img/urunler/ai-generated/KY-600-hero.png", "/assets/img/urunler/ai-generated/KY-600-dims.png", "/assets/img/urunler/ai-generated/KY-600-wheel.png", "/assets/img/urunler/ai-generated/KY-600-material.png"] },
